import math


def _num(d, key, default=0.0):
    if not isinstance(d, dict):
        return float(default)
    v = d.get(key, default)
    if v is None:
        return float(default)
    try:
        f = float(v)
    except (TypeError, ValueError):
        return float(default)
    if math.isnan(f) or math.isinf(f):
        return float(default)
    return f


def _mag(v):
    if v is None:
        return 0.0
    if isinstance(v, (int, float)):
        f = float(v)
        return 0.0 if (math.isnan(f) or math.isinf(f)) else abs(f)
    if isinstance(v, (list, tuple)):
        vals = [_mag(c) for c in v]
        return math.sqrt(sum(c * c for c in vals))
    if isinstance(v, dict):
        vals = [_mag(c) for c in v.values()]
        return math.sqrt(sum(c * c for c in vals))
    return 0.0


def _clamp(x, lo, hi):
    return max(lo, min(hi, x))


def score(ep: dict) -> float:
    outcome = ep.get("outcome", "")
    success = bool(ep.get("success", False) or outcome == "success")
    fell = bool(ep.get("fell", False) or outcome == "fell")
    collided = bool(ep.get("collided", False) or outcome == "collided")
    near_miss = bool(ep.get("near_miss", False) or outcome == "near_miss")
    stalled = bool(ep.get("stalled", False) or outcome == "stalled")
    timeout = bool(outcome == "timeout" or (not success and not fell and not collided and not stalled))

    duration = max(0.0, _num(ep, "duration", 0.0))
    peak_impact = max(0.0, _num(ep, "peak_impact", 0.0))
    max_tilt_deg = max(0.0, _num(ep, "max_tilt_deg", 0.0))
    jerk = max(0.0, _num(ep, "jerk", 0.0))

    edge_speed_raw = ep.get("edge_speed", None)
    edge_heading_raw = ep.get("edge_heading_deg", None)
    min_clearance_raw = ep.get("min_clearance", None)
    min_clearance = _num(ep, "min_clearance", 99.0) if min_clearance_raw is not None else 99.0

    states = ep.get("states") or []
    n = len(states)

    effective_collision = collided or (peak_impact > 15.0) or (min_clearance_raw is not None and min_clearance < 0.05)
    safe_success = success and not fell and not effective_collision and not stalled
    clean_success = safe_success and not near_miss and (min_clearance >= 0.25)

    # 1. Trajectory progress & lateral bypass shaping
    if n > 0:
        start_x = _num(states[0], "x", -1.0)
        start_y = _num(states[0], "y", 0.0)
        final_x = _num(states[-1], "x", start_x)
        max_x = max(_num(s, "x", start_x) for s in states)
        max_lat = max(abs(_num(s, "y", start_y) - start_y) for s in states)

        target_span = max(0.5, 1.25 - start_x)
        raw_disp = _clamp((final_x - start_x) / target_span, -0.5, 1.25)
        max_disp = _clamp((max_x - start_x) / target_span, 0.0, 1.25)
        backtrack_m = max(0.0, max_x - final_x)
        lat_bypass = _clamp(max_lat / 0.65, 0.0, 1.0)
    else:
        raw_disp = 1.0 if success else 0.0
        max_disp = 1.0 if success else 0.0
        backtrack_m = 0.0
        lat_bypass = 0.5 if success else 0.0

    total = 0.0
    if safe_success:
        total += 55.0 * raw_disp + 15.0 * max_disp + 15.0 * lat_bypass
    elif not effective_collision:
        # Strong dense gradient for steering laterally around the obstacle and advancing past it
        total += 35.0 * raw_disp + 10.0 * max_disp + 18.0 * lat_bypass * max(0.2, max_disp)
    else:
        # Even on collision episodes, reward lateral evasion attempts over head-on crashes
        total += 8.0 * max(0.0, raw_disp) + 12.0 * lat_bypass

    total -= 12.0 * _clamp(backtrack_m, 0.0, 1.5)

    # 2. Strict terminal hierarchy (collision > stall/timeout > near_miss success > clean success)
    if clean_success:
        total += 180.0
        if duration > 0.0:
            total += _clamp(15.0 - 1.5 * max(0.0, duration - 2.5), 0.0, 15.0)
    elif safe_success:
        # Succeeding with a tight clearance still gets a strong positive reward so RL learns the bypass first
        total += 130.0
    elif success:
        total += 30.0

    if fell:
        total -= 220.0
    if effective_collision:
        total -= 190.0
    if stalled:
        # Stalling in place is strictly worse than attempting a bypass, and cannot beat collision unless evading
        total -= 145.0
    if timeout and not success:
        total -= 120.0
    if near_miss and not safe_success:
        total -= 35.0

    # 3. Smooth obstacle clearance shaping (realistic threshold when spawning near an obstacle)
    if min_clearance_raw is not None:
        safe_dist = 0.45
        if min_clearance < safe_dist:
            deficit = (safe_dist - max(0.0, min_clearance)) / safe_dist
            total -= 40.0 * (deficit ** 2)
            if min_clearance < 0.15:
                total -= 35.0 * ((0.15 - max(0.0, min_clearance)) / 0.15)
        elif safe_success:
            total += 18.0 * _clamp((min_clearance - safe_dist) / 0.45, 0.0, 1.0)

    # 4. Edge speed & heading stability
    if edge_heading_raw is not None:
        edge_heading = abs(_num(ep, "edge_heading_deg", 0.0))
        allowed_hdg = 35.0
        if edge_heading > allowed_hdg:
            excess_h = edge_heading - allowed_hdg
            total -= 0.35 * excess_h + 0.015 * (excess_h ** 2)
        elif clean_success:
            total += 6.0 * ((allowed_hdg - edge_heading) / allowed_hdg) ** 2

    if edge_speed_raw is not None:
        edge_speed = max(0.0, _num(ep, "edge_speed", 0.0))
        if edge_speed > 0.80:
            excess_v = edge_speed - 0.80
            total -= 22.0 * excess_v + 25.0 * (excess_v ** 2)
        if 0.25 <= edge_speed <= 0.75 and safe_success:
            center_err = abs(edge_speed - 0.50) / 0.25
            total += 8.0 * max(0.0, 1.0 - center_err ** 2)

    # 5. Impact, tilt & jerk penalties
    if peak_impact > 2.0:
        imp_excess = peak_impact - 2.0
        total -= _clamp(3.0 * imp_excess + 0.25 * (imp_excess ** 2), 0.0, 95.0)
    elif clean_success:
        total += 8.0 * ((2.0 - peak_impact) / 2.0) ** 2

    if max_tilt_deg > 12.0:
        tilt_excess = max_tilt_deg - 12.0
        total -= _clamp(1.2 * tilt_excess + 0.08 * (tilt_excess ** 2), 0.0, 45.0)
    elif clean_success:
        total += 5.0 * ((12.0 - max_tilt_deg) / 12.0)

    if jerk > 0.45:
        jerk_excess = jerk - 0.45
        total -= _clamp(8.0 * jerk_excess + 2.0 * (jerk_excess ** 2), 0.0, 35.0)
    elif clean_success:
        total += 8.0 * ((0.45 - jerk) / 0.45) ** 2

    # 6. Per-tick trajectory quality & active steering encouragement
    if n > 0:
        roll_pen_sum = 0.0
        pitch_pen_sum = 0.0
        gyro_pen_sum = 0.0
        reverse_pen_sum = 0.0
        cmd_osc_sum = 0.0
        surging_pen_sum = 0.0
        idle_pen_sum = 0.0
        steer_evade_bonus_sum = 0.0

        for i, s in enumerate(states):
            roll = abs(_num(s, "roll_deg", 0.0))
            pitch = abs(_num(s, "pitch_deg", 0.0))
            spd = _num(s, "speed", 0.0)
            cmd_v = _num(s, "cmd_v", spd)
            cmd_w = _num(s, "cmd_w", 0.0)
            gyro_m = _mag(s.get("gyro", 0.0))
            s_clr = _num(s, "clearance", _num(s, "min_clearance", min_clearance))

            if roll > 3.5:
                roll_pen_sum += 0.35 * (roll - 3.5) + 0.04 * ((roll - 3.5) ** 2)
            if pitch > 12.0:
                pitch_pen_sum += 0.25 * (pitch - 12.0) + 0.03 * ((pitch - 12.0) ** 2)
            if gyro_m > 1.8:
                gyro_pen_sum += 1.2 * (gyro_m - 1.8)
            if cmd_v < -0.05:
                reverse_pen_sum += 3.0 * abs(cmd_v)

            # Penalize sitting still when not succeeded
            if spd < 0.10 and not safe_success:
                idle_pen_sum += 1.5 * ((0.10 - max(0.0, spd)) / 0.10)

            # Reward active steering when close to the obstacle while moving at a controlled speed
            if s_clr < 0.70 and 0.10 <= spd <= 0.65 and abs(cmd_w) >= 0.25:
                steer_evade_bonus_sum += _clamp(abs(cmd_w) / 1.0, 0.0, 1.0)

            if i > 0:
                prev = states[i - 1]
                dt = max(1e-3, _num(s, "t", i * 0.05) - _num(prev, "t", (i - 1) * 0.05))
                prev_cv = _num(prev, "cmd_v", _num(prev, "speed", 0.0))
                prev_cw = _num(prev, "cmd_w", 0.0)
                prev_spd = _num(prev, "speed", 0.0)

                d_cv = abs(cmd_v - prev_cv) / dt
                d_cw = abs(cmd_w - prev_cw) / dt
                d_spd = abs(spd - prev_spd) / dt

                if d_cv > 1.0:
                    cmd_osc_sum += 0.6 * (d_cv - 1.0)
                if d_cw > 2.2:
                    cmd_osc_sum += 0.3 * (d_cw - 2.2)
                if d_spd > 1.8:
                    surging_pen_sum += 0.6 * (d_spd - 1.8)

        inv_n = 1.0 / float(n)
        total -= _clamp(roll_pen_sum * inv_n * 6.0, 0.0, 20.0)
        total -= _clamp(pitch_pen_sum * inv_n * 5.0, 0.0, 15.0)
        total -= _clamp(gyro_pen_sum * inv_n * 4.0, 0.0, 15.0)
        total -= _clamp(reverse_pen_sum * inv_n * 5.0, 0.0, 15.0)
        total -= _clamp(cmd_osc_sum * inv_n * 3.0, 0.0, 18.0)
        total -= _clamp(surging_pen_sum * inv_n * 3.5, 0.0, 18.0)
        total -= _clamp(idle_pen_sum * inv_n * 20.0, 0.0, 28.0)

        if not effective_collision:
            total += _clamp(steer_evade_bonus_sum * inv_n * 14.0, 0.0, 14.0)

        mean_pen = (roll_pen_sum + cmd_osc_sum + surging_pen_sum + reverse_pen_sum + idle_pen_sum) * inv_n
        if mean_pen < 0.8 and clean_success:
            total += 10.0 * ((0.8 - mean_pen) / 0.8)

    return float(total)
